DERIVS += [
 D('heisenberg-ho', 'Heisenberg picture: the oscillator operators in time', 'formalism-and-uncertainty', 'heisenberg-picture',
   r'Show $\frac{d}{dt}\hat A_H=\frac i\hbar[\hat H,\hat A_H]$ and solve it for $\hat x_H(t)$, $\hat p_H(t)$ and $\hat a_H(t)$ of the harmonic oscillator.',
   [r'$\hat U=e^{-i\hat Ht/\hbar}$, $\hat A_H(t)=\hat U^\dagger\hat A\hat U$; since $\hat H$ commutes with $\hat U$: $\frac{d}{dt}\hat A_H=\frac i\hbar\hat U^\dagger[\hat H,\hat A]\hat U=\frac i\hbar[\hat H,\hat A_H]$.',
    r'$[\hat H,\hat x]=-\frac{i\hbar}m\hat p$ and $[\hat H,\hat p]=\big[\frac12m\omega^2\hat x^2,\hat p\big]=i\hbar m\omega^2\hat x$.',
    r'So $\dot{\hat x}_H=\frac{\hat p_H}m$ and $\dot{\hat p}_H=-m\omega^2\hat x_H$: the classical equations, now for operators.',
    r'$\hat x_H(t)=\hat x\cos\omega t+\frac{\hat p}{m\omega}\sin\omega t$, $\hat p_H(t)=\hat p\cos\omega t-m\omega\hat x\sin\omega t$.',
    r'$[\hat H,\hat a]=-\hbar\omega\hat a$, so $\dot{\hat a}_H=-i\omega\hat a_H$ and $\hat a_H(t)=\hat a\,e^{-i\omega t}$.'],
   [r'Differentiate $\hat U^\dagger\hat A\hat U$: the commutator with $\hat H$', 'Two commutators give operator versions of Newton', 'Solve like the classical oscillator, with the initial operators as constants'],
   [W(0, r'Why are expectation values the same in both pictures?', [r'$\langle\psi(t)|\hat A|\psi(t)\rangle=\langle\psi(0)|\hat U^\dagger\hat A\hat U|\psi(0)\rangle$: the time dependence is only moved from the state to the operator', r'Because $\hat A$ commutes with $\hat H$', r'Because $\hat U$ is Hermitian', 'Because the states do not change'],
      r'$\hat U$ is unitary, not Hermitian; that is why it can be moved from the ket and bra onto the operator.')],
   V(r'Replace the oscillator by a constant force: $\hat H=\frac{\hat p^2}{2m}-F\hat x$.', r'Find $\hat x_H(t)$.',
     r'$[\hat H,\hat p]=-F[\hat x,\hat p]=-i\hbar F$, so $\dot{\hat p}_H=F$, and still $\dot{\hat x}_H=\hat p_H/m$.',
     r'$\hat p_H(t)=\hat p+Ft$ and $\hat x_H(t)=\hat x+\frac{\hat p}mt+\frac{F}{2m}t^2$: the wave packet’s centre falls like a classical particle, and its width grows as for a free particle.')),

 D('spin-precession', 'Spin precession in a magnetic field', 'spin-addition-stern-gerlach', 'spin-in-b-field',
   r'Spin $\frac12$ with $\hat H=\omega\hat S_z$ (from $\hat H=-\gamma\mathbf B\cdot\hat{\mathbf S}$ with $\mathbf B=B\hat z$, $\omega=-\gamma B$). The spin starts along $+x$. Find $\langle\hat{\mathbf S}\rangle(t)$.',
   [r'Eigenstates $|\!\uparrow\rangle$, $|\!\downarrow\rangle$ with energies $\pm\frac{\hbar\omega}2$.',
    r'$|\psi(0)\rangle=\frac1{\sqrt2}(|\!\uparrow\rangle+|\!\downarrow\rangle)$, so $|\psi(t)\rangle=\frac1{\sqrt2}\big(e^{-i\omega t/2}|\!\uparrow\rangle+e^{i\omega t/2}|\!\downarrow\rangle\big)$.',
    r'Up to a global phase: $\frac1{\sqrt2}\big(|\!\uparrow\rangle+e^{i\omega t}|\!\downarrow\rangle\big)$, the spin state pointing at the azimuth $\varphi=\omega t$ in the $xy$ plane.',
    r'$\langle\hat S_x\rangle=\frac\hbar2\cos\omega t$, $\langle\hat S_y\rangle=\frac\hbar2\sin\omega t$, $\langle\hat S_z\rangle=0$: the spin precesses about $\mathbf B$ with angular frequency $\omega$.'],
   ['Energy eigenstates of the field direction', r'Each component picks up $e^{-iEt/\hbar}$', 'Only the relative phase matters: it is the azimuth of the spin'],
   [W(2, r'Why may the factor $e^{-i\omega t/2}$ be dropped?', ['A global phase does not change any expectation value', r'Because $\omega t$ is small', r'Because $|\!\uparrow\rangle$ and $|\!\downarrow\rangle$ are orthogonal', 'Because the state is normalised'],
      r'Only the relative phase between the components is measurable; here it grows as $\omega t$, which is the precession.')],
   V(r'The field points along $x$: $\hat H=\omega\hat S_x$, and the spin starts in $|\!\uparrow\rangle$.', r'Find the probability to find $|\!\downarrow\rangle$ at time $t$.',
     r'Now $|\!\uparrow\rangle=\frac1{\sqrt2}(|+x\rangle+|-x\rangle)$ is the superposition, and the phase builds up between $|\pm x\rangle$.',
     r'The spin rotates about $x$: $\langle\hat S_z\rangle=\frac\hbar2\cos\omega t$ and $P_\downarrow(t)=\sin^2\frac{\omega t}2$ (a full flip after $t=\pi/\omega$).')),

 D('coherent', 'Coherent states of the oscillator', 'harmonic-oscillator-elevator', 'ho-ladder',
   r'Find the normalised eigenstates $|\alpha\rangle$ of $\hat a$, the distribution of $n$, and how $|\alpha\rangle$ evolves in time.',
   [r'Write $|\alpha\rangle=\sum_nc_n|n\rangle$. With $\hat a|n\rangle=\sqrt n|n-1\rangle$, $\hat a|\alpha\rangle=\alpha|\alpha\rangle$ gives $\sqrt{n+1}\,c_{n+1}=\alpha c_n$.',
    r'So $c_n=\frac{\alpha^n}{\sqrt{n!}}c_0$.',
    r'Normalise: $|c_0|^2\sum_n\frac{|\alpha|^{2n}}{n!}=|c_0|^2e^{|\alpha|^2}=1$, so $c_0=e^{-|\alpha|^2/2}$.',
    r'$P(n)=e^{-|\alpha|^2}\frac{|\alpha|^{2n}}{n!}$: a Poisson distribution with mean $\langle n\rangle=|\alpha|^2$.',
    r'In time, $c_n\to c_ne^{-i\omega(n+\frac12)t}$: this is $|\alpha e^{-i\omega t}\rangle$ times $e^{-i\omega t/2}$. It stays coherent, and $\langle\hat x\rangle=\sqrt{\frac{2\hbar}{m\omega}}\,\mathrm{Re}(\alpha e^{-i\omega t})$ oscillates classically.'],
   [r'Expand in $|n\rangle$ and compare coefficients: a recursion', r'Normalise with the exponential series', r'Time evolution only rotates $\alpha$'],
   [W(4, r'Why does $|\alpha\rangle$ remain an eigenstate of $\hat a$ in time?', [r'Each $c_n$ picks up $(e^{-i\omega t})^n$ (apart from a common phase), which can be absorbed into $\alpha^n$', r'Because $\hat a$ commutes with $\hat H$', r'Because $|\alpha\rangle$ is an energy eigenstate', 'Because the Poisson distribution is stationary'],
      r'$\hat a$ does not commute with $\hat H$ ($[\hat H,\hat a]=-\hbar\omega\hat a$), and $|\alpha\rangle$ is not stationary: the phases are equally spaced, which is what keeps the form.')],
   V(r'Look for eigenstates of $\hat a^\dagger$ instead of $\hat a$.', 'Do they exist?',
     r'$\hat a^\dagger|\beta\rangle=\beta|\beta\rangle$ with $|\beta\rangle=\sum c_n|n\rangle$: the $|0\rangle$ component gives $\beta c_0=0$, and in general $\sqrt n\,c_{n-1}=\beta c_n$.',
     r'For $\beta\ne0$: $c_0=0$, then $c_1=0$, and so on; for $\beta=0$: $c_{n-1}=0$ for all $n$. Only the zero vector: $\hat a^\dagger$ has no eigenstates.')),

 D('golden-rule', 'Fermi’s golden rule', 'perturbation-forge', 'pt-time-dependent',
   r'A constant perturbation $\hat V$ is switched on at $t=0$. Derive the transition rate from $|i\rangle$ into a continuum of final states with density $\rho(E)$.',
   [r'First order in the interaction picture: $c_f(t)=\frac1{i\hbar}\int_0^t\langle f|\hat V|i\rangle e^{i\omega_{fi}t^\prime}dt^\prime$ with $\omega_{fi}=(E_f-E_i)/\hbar$.',
    r'$c_f(t)=-\frac{V_{fi}}{\hbar\omega_{fi}}\big(e^{i\omega_{fi}t}-1\big)$.',
    r'$|c_f(t)|^2=\frac{|V_{fi}|^2}{\hbar^2}\,\frac{\sin^2(\omega_{fi}t/2)}{(\omega_{fi}/2)^2}$.',
    r'For large $t$, $\frac{\sin^2(\omega t/2)}{(\omega/2)^2}\to2\pi t\,\delta(\omega)$: $|c_f|^2\to\frac{2\pi}\hbar|V_{fi}|^2\,t\,\delta(E_f-E_i)$, growing linearly in $t$.',
    r'Sum over the continuum, $\sum_f\to\int dE_f\,\rho(E_f)$: the rate is $\Gamma=\frac{2\pi}\hbar|V_{fi}|^2\rho(E_i)$.'],
   ['First-order amplitude: integral of the matrix element with the phase', 'The squared amplitude is a peak in energy of width about $2\pi/t$ and height $t^2$', 'Its area grows like $t$; summing over the continuum gives a constant rate'],
   [W(4, 'Why does a continuum of final states give a constant rate, while a single final state only oscillates?', [r'Summing over states, the peak (height $\propto t^2$, width $\propto1/t$) has an area $\propto t$', 'Because the continuum absorbs energy', r'Because $\hat V$ is constant', 'Because of energy conservation alone'],
      r'For one final state $|c_f|^2$ oscillates and never grows without bound; only the sum over many nearly degenerate states turns into a rate.')],
   V(r'A periodic perturbation $\hat V(t)=\hat F e^{-i\omega t}+\hat F^\dagger e^{i\omega t}$ instead of a constant one.', 'What changes in the rate?',
     r'Each term shifts the phase in the time integral: $\omega_{fi}\to\omega_{fi}\mp\omega$.',
     r'$\Gamma_{i\to f}=\frac{2\pi}\hbar|F_{fi}|^2\delta(E_f-E_i-\hbar\omega)+\frac{2\pi}\hbar|(F^\dagger)_{fi}|^2\delta(E_f-E_i+\hbar\omega)$: absorption and stimulated emission of one quantum $\hbar\omega$.')),

 D('radial', 'Central potential: separation and the radial equation', 'hydrogen-lamp', 'central-potential',
   r'For $\hat H=\frac{\hat{\mathbf p}^2}{2m}+V(r)$, separate the variables and derive the radial equation for $u(r)=rR(r)$.',
   [r'$\hat{\mathbf p}^2=-\hbar^2\nabla^2=-\hbar^2\frac1r\partial_r^2\,r+\frac{\hat{\mathbf L}^2}{r^2}$.',
    r'$\hat{\mathbf L}^2$ and $\hat L_z$ act only on the angles and commute with $\hat H$: $\psi=R(r)\,Y_{lm}(\theta,\varphi)$ with $\hat{\mathbf L}^2\to\hbar^2l(l+1)$.',
    r'With $u=rR$: $-\frac{\hbar^2}{2m}u^{\prime\prime}+\Big[V(r)+\frac{\hbar^2l(l+1)}{2mr^2}\Big]u=Eu$.',
    r'Boundary conditions: $u(0)=0$ (so that $R$ stays finite) and $\int_0^\infty|u|^2dr=1$.',
    r'The energy does not depend on $m$: every level is at least $(2l+1)$-fold degenerate.'],
   [r'Split $\nabla^2$ into a radial part and $\hat{\mathbf L}^2/r^2$', r'Angular part: $Y_{lm}$', r'$u=rR$ turns it into a 1D problem with the centrifugal term'],
   [W(4, r'Why can $E$ not depend on $m$?', [r'$\hat L_\pm$ commute with $\hat H$ and change only $m$, so all $2l+1$ states of a multiplet have the same energy', r'Because $V$ depends only on $r$ and $m$ does not appear in $V$', r'Because $\hat L_z$ is conserved', 'Because of parity'],
      r'Conservation of $\hat L_z$ alone would allow $E$ to depend on $m$; it is the full rotation symmetry (all $\hat L_i$, hence $\hat L_\pm$) that forces the degeneracy.')],
   V(r'An infinite spherical well ($V=0$ for $r<a$, infinite outside), and only $l=0$.', 'Find the energies.',
     r'For $l=0$ there is no centrifugal term: $u^{\prime\prime}=-k^2u$ with $u(0)=0$ and $u(a)=0$.',
     r'$u=\sin kr$, $ka=n\pi$: $E_n=\frac{\hbar^2\pi^2n^2}{2ma^2}$, the same numbers as the 1D box, with $R=\frac{\sin kr}{r}$ finite at the centre.')),

 D('cg-1-half', r'Clebsch–Gordan coefficients for $1\otimes\frac12$', 'spin-addition-stern-gerlach', 'spin-addition',
   r'Couple $l=1$ and $s=\frac12$: find the states $|j,m\rangle$ with $m=\frac12$ in terms of $|m_l\rangle|m_s\rangle$.',
   [r'$j=\frac32$ (4 states) or $j=\frac12$ (2 states): $3\cdot2=4+2$.',
    r'The only product state with $m=\frac32$ is $|1\rangle|\!\uparrow\rangle$, so $|\tfrac32,\tfrac32\rangle=|1\rangle|\!\uparrow\rangle$.',
    r'$\hat J_-|\tfrac32,\tfrac32\rangle=\hbar\sqrt3\,|\tfrac32,\tfrac12\rangle$ and $(\hat L_-+\hat S_-)|1\rangle|\!\uparrow\rangle=\hbar\sqrt2\,|0\rangle|\!\uparrow\rangle+\hbar\,|1\rangle|\!\downarrow\rangle$.',
    r'So $|\tfrac32,\tfrac12\rangle=\sqrt{\tfrac23}\,|0\rangle|\!\uparrow\rangle+\sqrt{\tfrac13}\,|1\rangle|\!\downarrow\rangle$.',
    r'$|\tfrac12,\tfrac12\rangle$ is the orthogonal $m=\frac12$ combination: $\sqrt{\tfrac23}\,|1\rangle|\!\downarrow\rangle-\sqrt{\tfrac13}\,|0\rangle|\!\uparrow\rangle$ (overall sign by the Condon–Shortley convention).'],
   ['Count the multiplets', 'Start at the top: the unique product state', r'Lower with $\hat J_-=\hat L_-+\hat S_-$ and compare both sides', 'The orthogonal partner starts the next multiplet'],
   [W(2, r'Where do $\sqrt3$ and $\sqrt2$ come from?', [r'$\hbar\sqrt{j(j+1)-m(m-1)}$ for $\hat J_-$ on $|\tfrac32,\tfrac32\rangle$ and for $\hat L_-$ on $|1,1\rangle$', 'From normalising the final state', r'From the dimension $2j+1$', 'From the Clebsch–Gordan tables'],
      r'$\frac{15}4-\frac34=3$ and $2-0=2$; for $\hat S_-|\!\uparrow\rangle$ the root is $\sqrt{\frac34+\frac14}=1$.')],
   V(r'Couple two spins $1$: $1\otimes1$.', r'Find $|2,1\rangle$ and $|1,1\rangle$.',
     r'$j=2,1,0$ ($9=5+3+1$); top $|2,2\rangle=|1\rangle|1\rangle$; $\hat J_-$ gives $2\hbar|2,1\rangle$ on the left and $\sqrt2\hbar(|0\rangle|1\rangle+|1\rangle|0\rangle)$ on the right.',
     r'$|2,1\rangle=\frac1{\sqrt2}(|1\rangle|0\rangle+|0\rangle|1\rangle)$ and $|1,1\rangle=\frac1{\sqrt2}(|1\rangle|0\rangle-|0\rangle|1\rangle)$ (Condon–Shortley sign).')),

 D('variational', 'Variational method', 'perturbation-forge', 'variational',
   r'Show $E_0\le\langle\psi|\hat H|\psi\rangle$ for every normalised $\psi$, and apply it to the oscillator with the trial function $\psi_b\propto e^{-bx^2}$.',
   [r'Expand $\psi=\sum_nc_n|n\rangle$ in eigenstates: $\langle\hat H\rangle=\sum_n|c_n|^2E_n\ge E_0\sum_n|c_n|^2=E_0$.',
    r'For $\psi_b=(2b/\pi)^{1/4}e^{-bx^2}$: $\langle x^2\rangle=\frac1{4b}$ and $\langle p^2\rangle=\hbar^2b$, so $E(b)=\frac{\hbar^2b}{2m}+\frac{m\omega^2}{8b}$.',
    r'$E^\prime(b)=0$: $\frac{\hbar^2}{2m}=\frac{m\omega^2}{8b^2}$, so $b=\frac{m\omega}{2\hbar}$.',
    r'$E(b)=\frac{\hbar\omega}4+\frac{\hbar\omega}4=\frac{\hbar\omega}2$: exact, because the true ground state is in the trial family.'],
   ['Expand in eigenstates: every $E_n\ge E_0$', r'Compute $\langle T\rangle$ and $\langle V\rangle$ for the trial family', 'Minimise over the parameter'],
   [W(0, r'Why is $\sum_n|c_n|^2E_n\ge E_0$?', [r'Every $E_n\ge E_0$ and the weights $|c_n|^2$ add up to 1', 'Because the energies are positive', r'Because $\hat H$ is Hermitian', 'Because the trial function is real'],
      r'It is a weighted average of energies that are all at least $E_0$; equality only when all weight is on the ground state.')],
   V(r'Use the same Gaussian for the quartic potential $V=\lambda x^4$.', 'Find the variational bound on the ground-state energy.',
     r'$\langle x^4\rangle=\frac3{16b^2}$, so $E(b)=\frac{\hbar^2b}{2m}+\frac{3\lambda}{16b^2}$; minimum at $b^3=\frac{3m\lambda}{4\hbar^2}$.',
     r'$E_0\le\big(\tfrac34\big)^{4/3}\big(\tfrac{\hbar^4\lambda}{m^2}\big)^{1/3}\approx0.681\big(\tfrac{\hbar^4\lambda}{m^2}\big)^{1/3}$; the exact value is about $0.668$ in the same units, so the bound is 2% above.')),

 D('finite-well', 'Finite well: even states always exist', 'wave-mechanics-basics', 'box-well-parity',
   r'$V=-V_0$ for $|x|<\frac a2$, zero outside. Derive the condition for the even bound states and show that at least one always exists.',
   [r'Inside: $\psi^{\prime\prime}=-k^2\psi$ with $k=\frac{\sqrt{2m(E+V_0)}}\hbar$; outside: $\psi\propto e^{-\kappa|x|}$ with $\kappa=\frac{\sqrt{-2mE}}\hbar$.',
    r'$V$ is even, so the bound states are even or odd; even: $\psi=\cos kx$ inside.',
    r'Match $\psi^\prime/\psi$ at $x=\frac a2$: $-k\tan\frac{ka}2=-\kappa$.',
    r'With $z=\frac{ka}2$ and $z_0=\frac a2\frac{\sqrt{2mV_0}}\hbar$ ($k^2+\kappa^2=\frac{2mV_0}{\hbar^2}$): $\tan z=\sqrt{\frac{z_0^2}{z^2}-1}$.',
    r'The left side rises from 0, the right side falls from $+\infty$ to 0 at $z=z_0$: they always cross once in $0<z<\min(z_0,\frac\pi2)$. At least one even bound state for any depth.'],
   ['Solve inside and outside', 'Use parity: even states first', r'Match the logarithmic derivative', 'Dimensionless graphical solution: always one crossing'],
   [W(1, 'Why may we look for even and odd solutions separately?', [r'Parity commutes with $\hat H$ when $V(-x)=V(x)$, and 1D bound states are non-degenerate, so each is even or odd', 'Because cosines and sines are a basis', 'Because the well is finite', 'Because the energy is negative'],
      r'In general only eigenstates can be chosen with definite parity; in 1D bound states are non-degenerate, so they automatically have it.'),
    W(2, r'Why match $\psi^\prime/\psi$ instead of $\psi$ and $\psi^\prime$ separately?', ['It removes the unknown amplitudes in one equation', r'Because $\psi^\prime$ jumps at the edge', 'Because the energy is unknown', 'It is only valid for even states'],
      r'Both $\psi$ and $\psi^\prime$ are continuous at a finite step; their ratio is too, and it does not depend on the normalisation of either side.')],
   V(r'Ask for the first odd bound state instead.', 'When does it exist?',
     r'Odd: $\sin kx$ inside, and the matching gives $\cot z=-\frac{\sqrt{z_0^2-z^2}}z$, which needs $\cot z<0$, i.e. $z>\frac\pi2$.',
     r'Only if $z_0>\frac\pi2$, i.e. $V_0a^2>\frac{\pi^2\hbar^2}{2m}$: a minimum depth. (The same condition decides whether a 3D square well binds an $s$-wave, since there $u(0)=0$ as for odd states.)')),
]
